settings.custom_liquid:
{% comment %}
  Wondear - HSA/FSA Reimbursement by Flex
  Suggested placement: under product price / above Add to Cart button
{% endcomment %}

<div class="wondear-flex-reimbursement" data-flex-reimbursement>
  <div class="wondear-flex-reimbursement__header">
    <div class="wondear-flex-reimbursement__icon" aria-hidden="true">
      <svg viewBox="0 0 24 24" fill="none">
        <path d="M12 2.75L19.25 6V11.4C19.25 15.95 16.18 20.18 12 21.25C7.82 20.18 4.75 15.95 4.75 11.4V6L12 2.75Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
        <path d="M8.8 12.15L10.9 14.25L15.45 9.7" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
    </div>

    <div class="wondear-flex-reimbursement__title-wrap">
      <p class="wondear-flex-reimbursement__eyebrow">HSA/FSA Reimbursement by Flex</p>
      <h3 class="wondear-flex-reimbursement__title">
        You may be eligible for reimbursement
      </h3>
    </div>
  </div>

  <div class="wondear-flex-reimbursement__body">
    <p class="wondear-flex-reimbursement__text">
      Complete a quick Flex consultation. If eligible, you’ll receive a Letter of Medical Necessity and can submit it with your Wondear receipt for HSA/FSA reimbursement.
    </p>

    <div class="wondear-flex-reimbursement__steps">
      <div class="wondear-flex-reimbursement__step">
        <span>1</span>
        <p>Complete Flex consultation</p>
      </div>
      <div class="wondear-flex-reimbursement__step">
        <span>2</span>
        <p>Purchase from Wondear</p>
      </div>
      <div class="wondear-flex-reimbursement__step">
        <span>3</span>
        <p>Submit for reimbursement</p>
      </div>
    </div>

    <a
      class="wondear-flex-reimbursement__button"
      href="https://www.withflex.com/brand/wondear"
      target="_blank"
      rel="noopener noreferrer"
    >
      Check Eligibility with Flex
      <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
        <path d="M7.5 4.5H15.5V12.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
        <path d="M15 5L5 15" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>
      </svg>
    </a>

    <p class="wondear-flex-reimbursement__note">
      Please use a standard credit or debit card at checkout. Do not use your HSA/FSA card at checkout.
    </p>
  </div>
</div>

<style>
  .wondear-flex-reimbursement {
    width: 100%;
    margin: 18px 0;
    padding: 18px;
    border-radius: 18px;
    background: #f3efe9;
    border: 1px solid rgba(17, 17, 17, 0.08);
    color: #111111;
    font-family: var(--font-body--family);
  }

  .wondear-flex-reimbursement__header {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 14px;
  }

  .wondear-flex-reimbursement__icon {
    flex: 0 0 42px;
    width: 42px;
    height: 42px;
    border-radius: 999px;
    background: #ebe4db;
    color: #111111;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .wondear-flex-reimbursement__icon svg {
    width: 24px;
    height: 24px;
  }

  .wondear-flex-reimbursement__title-wrap {
    min-width: 0;
  }

  .wondear-flex-reimbursement__eyebrow {
    margin: 0 0 5px;
    font-size: 12px;
    line-height: 1.2;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #8a8177;
  }

  .wondear-flex-reimbursement__title {
    margin: 0;
    font-family: var(--font-heading--family);
    font-size: clamp(18px, 1.5vw, 22px);
    line-height: 1.18;
    font-weight: 700;
    color: #111111;
  }

  .wondear-flex-reimbursement__body {
    display: block;
  }

  .wondear-flex-reimbursement__text {
    margin: 0 0 14px;
    font-size: 14px;
    line-height: 1.55;
    font-weight: 400;
    color: #6f6a63;
  }

  .wondear-flex-reimbursement__steps {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
    margin: 0 0 14px;
  }

  .wondear-flex-reimbursement__step {
    padding: 10px 8px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.48);
    border: 1px solid rgba(17, 17, 17, 0.06);
  }

  .wondear-flex-reimbursement__step span {
    width: 22px;
    height: 22px;
    margin: 0 0 7px;
    border-radius: 999px;
    background: #111111;
    color: #ffffff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    line-height: 1;
    font-weight: 700;
  }

  .wondear-flex-reimbursement__step p {
    margin: 0;
    font-size: 12px;
    line-height: 1.35;
    font-weight: 600;
    color: #111111;
  }

  .wondear-flex-reimbursement__button {
    width: 100%;
    min-height: 46px;
    padding: 0 18px;
    border-radius: 999px;
    background: #111111;
    color: #ffffff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-size: 14px;
    line-height: 1;
    font-weight: 700;
    text-decoration: none;
    transition: opacity 0.2s ease, transform 0.2s ease;
  }

  .wondear-flex-reimbursement__button:hover {
    color: #ffffff;
    opacity: 0.88;
    transform: translateY(-1px);
  }

  .wondear-flex-reimbursement__button svg {
    width: 16px;
    height: 16px;
  }

  .wondear-flex-reimbursement__note {
    margin: 12px 0 0;
    font-size: 12px;
    line-height: 1.45;
    color: #8a8177;
  }

  @media screen and (max-width: 749px) {
    .wondear-flex-reimbursement {
      margin: 16px 0;
      padding: 16px;
      border-radius: 16px;
    }

    .wondear-flex-reimbursement__header {
      gap: 10px;
    }

    .wondear-flex-reimbursement__icon {
      flex-basis: 38px;
      width: 38px;
      height: 38px;
    }

    .wondear-flex-reimbursement__title {
      font-size: 18px;
    }

    .wondear-flex-reimbursement__steps {
      grid-template-columns: 1fr;
      gap: 7px;
    }

    .wondear-flex-reimbursement__step {
      display: flex;
      align-items: center;
      gap: 9px;
      padding: 9px 10px;
    }

    .wondear-flex-reimbursement__step span {
      margin: 0;
      flex: 0 0 22px;
    }

    .wondear-flex-reimbursement__button {
      min-height: 48px;
    }
  }
</style>
